mapper.select:
select from `ry_rental`.`ry_rental_audit_log` a left join `ry_rental`.`ry_rental_merchant_user` u on u.merchant_user_id = a.actor_id and u.tenant_id = a.tenant_id and u.member_id = a.member_id and u.is_delete = 0 where a.tenant_id = #{tenantId} and a.member_id = #{memberId} and a.actor_type = 'merchant_user' and a.is_delete = 0
and a.business_module like concat('%', #{query.businessModule}, '%')
and a.operation_type = #{query.operationType}
and coalesce(nullif(u.user_name, ''), a.actor_name) like concat('%', #{query.username}, '%')
and coalesce(nullif(u.nick_name, ''), a.actor_name) like concat('%', #{query.operatorName}, '%')
and a.description like concat('%', #{query.description}, '%')
and a.client_ip like concat('%', #{query.ipAddress}, '%')
and a.status = #{query.status}
and a.create_time >= #{query.params.beginTime}
and a.create_time <= #{query.params.endTime}
order by a.create_time desc, a.audit_id desc
